class Solution:
    def shortestDistance(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]: return -1
        m, n = len(grid), len(grid[0])
        total_dist = [[0] * n for _ in range(m)]
        reach_count = [[0] * n for _ in range(m)]
        building_count = 0
        for r in range(m):
            for c in range(n):
                if grid[r][c] == 1:
                    building_count += 1
                    q = deque([(r, c, 0)])
                    visited = set([(r, c)])
                    while q:
                        curr_r, curr_c, d = q.popleft()
                        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited and grid[nr][nc] == 0:
                                visited.add((nr, nc))
                                total_dist[nr][nc] += d + 1
                                reach_count[nr][nc] += 1
                                q.append((nr, nc, d + 1))
        min_dist = float("inf")
        for r in range(m):
            for c in range(n):
                if grid[r][c] == 0 and reach_count[r][c] == building_count:
                    min_dist = min(min_dist, total_dist[r][c])
        return min_dist if min_dist != float("inf") else -1

