class Solution {
public:
    int shortestDistance(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> totalDist(m, vector<int>(n, 0));
        vector<vector<int>> reach(m, vector<int>(n, 0));
        int buildings = 0;
        int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 1) {
                    buildings++;
                    queue<pair<int, int>> q;
                    vector<vector<bool>> vis(m, vector<bool>(n, false));
                    q.push({r, c});
                    vis[r][c] = true;
                    int d = 0;
                    while (!q.empty()) {
                        d++;
                        int sz = q.size();
                        while (sz--) {
                            auto [cr, cc] = q.front(); q.pop();
                            for (auto& dir : dirs) {
                                int nr = cr + dir[0], nc = cc + dir[1];
                                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !vis[nr][nc] && grid[nr][nc] == 0) {
                                    vis[nr][nc] = true;
                                    totalDist[nr][nc] += d;
                                    reach[nr][nc]++;
                                    q.push({nr, nc});
                                }
                            }
                        }
                    }
                }
            }
        }
        int ans = INT_MAX;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 0 && reach[r][c] == buildings) ans = min(ans, totalDist[r][c]);
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

