class Solution {
    public int shortestDistance(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[][] totalDist = new int[m][n];
        int[][] reach = new int[m][n];
        int buildings = 0;
        int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    buildings++;
                    Queue<int[]> q = new LinkedList<>();
                    boolean[][] vis = new boolean[m][n];
                    q.add(new int[]{r, c});
                    vis[r][c] = true;
                    int d = 0;
                    while (!q.isEmpty()) {
                        d++;
                        int sz = q.size();
                        while (sz-- > 0) {
                            int[] cell = q.poll();
                            for (int[] dir : dirs) {
                                int nr = cell[0] + dir[0], nc = cell[1] + dir[1];
                                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !vis[nr][nc] && grid[nr][nc] == 0) {
                                    vis[nr][nc] = true;
                                    totalDist[nr][nc] += d;
                                    reach[nr][nc]++;
                                    q.add(new int[]{nr, nc});
                                }
                            }
                        }
                    }
                }
            }
        }
        int ans = Integer.MAX_VALUE;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0 && reach[r][c] == buildings) ans = Math.min(ans, totalDist[r][c]);
            }
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
};

