var shortestDistance = function(grid) {
    const m = grid.length, n = grid[0].length;
    const totalDist = Array.from({ length: m }, () => Array(n).fill(0));
    const reach = Array.from({ length: m }, () => Array(n).fill(0));
    let buildings = 0;
    const dirs = [[0,1],[0,-1],[1,0],[-1,0]];
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1) {
                buildings++;
                const q = [[r, c]];
                const vis = Array.from({ length: m }, () => Array(n).fill(false));
                vis[r][c] = true;
                let d = 0;
                while (q.length) {
                    d++;
                    let sz = q.length;
                    while (sz--) {
                        const [cr, cc] = q.shift();
                        for (const [dr, dc] of dirs) {
                            const nr = cr + dr, nc = cc + dc;
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !vis[nr][nc] && grid[nr][nc] === 0) {
                                vis[nr][nc] = true;
                                totalDist[nr][nc] += d;
                                reach[nr][nc]++;
                                q.push([nr, nc]);
                            }
                        }
                    }
                }
            }
        }
    }
    let ans = Infinity;
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 0 && reach[r][c] === buildings) ans = Math.min(ans, totalDist[r][c]);
        }
    }
    return ans === Infinity ? -1 : ans;
};
